using System;using System.IO;using System.Text.Json;using System.Collections.Generic;using Exoduser.UnityPort.Core;
class Program {
 static int failed;static readonly List<object> Checks=new List<object>();static readonly JsonSerializerOptions Options=new JsonSerializerOptions{IncludeFields=true};
 static void Check(bool ok,string name){Checks.Add(new{name,passed=ok});if(!ok){failed++;Console.WriteLine("FAIL "+name);}}
 static bool Near(double a,double b)=>Math.Abs(a-b)<.00001;
 static InventoryState Fresh(JsonElement o)=>new InventoryState(JsonSerializer.Deserialize<InventorySeedData>(o.GetProperty("starting").GetRawText(),Options));
 static void Compare(InventoryStats stats,JsonElement source,string name){foreach(var p in source.EnumerateObject()){var f=typeof(InventoryStats).GetField(p.Name);if(f!=null)Check(Near(Convert.ToDouble(f.GetValue(stats)),p.Value.GetDouble()),name+" / "+p.Name);}}
 static PlayerState Full(InventoryStats s)=>new PlayerState{Hp=s.PlayerMaxHp,Stamina=(float)s.PlayerMaxStamina,Mana=(float)s.PlayerMaxMana,Shield=(float)s.PlayerMaxShield};
 static void Resources(PlayerState p,JsonElement source,string name){Check(Near(p.Hp,source.GetProperty("hp").GetDouble())&&Near(p.Stamina,source.GetProperty("st").GetDouble())&&Near(p.Mana,source.GetProperty("mp").GetDouble())&&Near(p.Shield,source.GetProperty("shield").GetDouble()),name+" preserves/clamps all current resources");}
 static int Main(string[] args){using(var doc=JsonDocument.Parse(File.ReadAllText(args[1]))){var o=doc.RootElement;var start=Fresh(o);Check(start.Bag.Count==10&&Array.FindAll(start.Equipped,i=>i!=null&&i.slot!="ossuary").Length==15,"original 15 equipped and 10 bag");var oss=start.GetEquipped("ossuary");Check(oss!=null&&oss.name=="전대의 유골함"&&oss.rarity==5&&oss.eDef==60&&oss.bonusMp==150&&oss.ancPow==.25&&oss.affixes.Length==1&&oss.affixes[0].id=="ancHP"&&oss._implicitStat=="_iAncPow"&&oss._implicitVal==10,"fixed unique ossuary is the 16th equipped item");Compare(start.CalculateStats(1),o.GetProperty("initialStats"),"initial source stats");
 for(int i=0;i<start.Bag.Count;i++)Check(InventoryState.ItemPower(start.Bag[i])==o.GetProperty("power")[i].GetInt32(),"actual source itemPower "+i);
 foreach(var profile in o.GetProperty("profiles").EnumerateArray())Compare(Fresh(o).CalculateStats(profile.GetProperty("level").GetInt32(),profile.GetProperty("stage").GetInt32(),profile.GetProperty("difficulty").GetInt32()),profile.GetProperty("stats"),"source level/difficulty/stage profile "+profile.GetProperty("level")+"/"+profile.GetProperty("difficulty"));
 foreach(var cell in o.GetProperty("grid").EnumerateArray()){var inv=Fresh(o);Check(inv.TryMove(inv.Bag[0],cell.GetProperty("x").GetInt32(),cell.GetProperty("y").GetInt32())==cell.GetProperty("allowed").GetBoolean(),"source grid oracle "+cell.GetProperty("x")+","+cell.GetProperty("y"));}
 foreach(var row in o.GetProperty("cases").EnumerateArray()){string name=row.GetProperty("name").GetString(),reason;var inv=Fresh(o);
  if(row.TryGetProperty("deferred",out _)){var before=inv.CalculateStats(1);Check(!inv.TryUnequip(row.GetProperty("slot").GetString(),out reason)&&inv.GetEquipped("ossuary")!=null&&inv.Bag.Count==10,name+" deferred: Unity refuses and leaves state unchanged");var after=inv.CalculateStats(1);Check(Near(before.PlayerMaxMana,after.PlayerMaxMana)&&before.PlayerMaxHp==after.PlayerMaxHp,name+" deferred: stats unchanged");continue;}
var p=Full(inv.CalculateStats(1));bool changed;if(row.TryGetProperty("index",out var idx))changed=inv.TryEquip(inv.Bag[idx.GetInt32()],1,out reason);else changed=inv.TryUnequip(row.GetProperty("slot").GetString(),out reason);
  var stats=inv.CalculateStats(1);stats.ClampResources(p);Compare(stats,row.GetProperty("stats"),name);Resources(p,row.GetProperty("stats"),name);
  int eq=0;bool equipment=true;foreach(var item in row.GetProperty("equipped").EnumerateArray()){equipment&=(inv.Equipped[eq++]?.name)==(item.ValueKind==JsonValueKind.Null?null:item.GetString());}Check(equipment,name+" source equipment order");
  bool bag=inv.Bag.Count==row.GetProperty("bag").GetArrayLength();int bi=0;foreach(var item in row.GetProperty("bag").EnumerateArray()){var actual=inv.Bag[bi++];bag&=actual.name==item.GetProperty("name").GetString()&&actual._gx==item.GetProperty("x").GetInt32()&&actual._gy==item.GetProperty("y").GetInt32();}Check(bag,name+" source bag and grid order");
 }
 {var inv=Fresh(o);var p=new PlayerState{Hp=50,Stamina=25,Mana=30,Shield=20};inv.TryEquip(inv.Bag.Find(i=>i.slot=="armor"),1,out _);var s=inv.CalculateStats(1);s.ClampResources(p);Compare(s,o.GetProperty("noHeal"),"source nonfull swap");Resources(p,o.GetProperty("noHeal"),"source nonfull swap");}
 {var inv=Fresh(o);var it=inv.Bag[0];Check(inv.Select(it)&&ReferenceEquals(inv.Selected,it),"selection uses owned reference");var unknown=new InventoryItem{slot="weapon",id=it.id};Check(!inv.Select(unknown)&&!inv.TryEquip(unknown,1,out _)&&!inv.TryMove(unknown,0,8),"foreign object cannot replace colliding ID");Check(!inv.TryMove(it,-1,0)&&!inv.TryMove(it,9,0)&&!inv.TryMove(it,0,119)&&!inv.TryMove(it,2,0),"grid rejects bounds and overlap without mutation");Check(it._gx==0&&it._gy==0&&inv.TryMove(it,1,5)&&it._gx==1&&it._gy==5,"grid allows free odd cell");it.reqLv=2;Check(!inv.TryEquip(it,1,out _)&&inv.Bag.Contains(it)&&it._gx==1,"required level rejects without mutation");it.reqLv=0;it.enh=1;Check(!inv.TryEquip(it,1,out _)&&inv.Bag.Contains(it),"enhanced item explicitly rejected");}
 {var inv=Fresh(o);var first=inv.Bag[0];var last=inv.Bag[9];last.fav=true;inv.Sort();Check(ReferenceEquals(inv.Bag[0],last),"favorite sorts ahead of power");last.fav=false;first.junk=true;inv.Sort();Check(ReferenceEquals(inv.Bag[9],first),"junk sorts last");inv.Select(first);inv.TryEquip(first,1,out _);Check(ReferenceEquals(inv.Selected,first)&&inv.Owns(first),"selection follows equip reference");}
 {var inv=Fresh(o);string reason;inv.TryUnequip("headband",out reason);var other=inv.GetEquipped("headband2");inv.TryUnequip("headband2",out reason);inv.TryEquip(other,1,out reason);Check(ReferenceEquals(inv.GetEquipped("headband"),other)&&other.slot=="headband","earring fills first empty slot and rewrites slot");}
 {var inv=Fresh(o);var eq=inv.GetEquipped("weapon");inv.Bag.Clear();for(int y=0;y<120;y+=2)for(int x=0;x<10;x+=2)inv.Bag.Add(new InventoryItem{slot="armor",_gx=x,_gy=y});Check(!inv.TryUnequip("weapon",out _)&&inv.Bag.Count==300&&ReferenceEquals(eq,inv.GetEquipped("weapon")),"full grid unequip rolls back without loss");}
 {var inv=Fresh(o);var o2=inv.GetEquipped("ossuary");string why;Check(!inv.TryUnequip("ossuary",out why)&&ReferenceEquals(inv.GetEquipped("ossuary"),o2),"ossuary unequip refused");var seed=JsonSerializer.Deserialize<InventorySeedData>(o.GetProperty("starting").GetRawText(),Options);seed.bag[0]=JsonSerializer.Deserialize<InventoryItem>(JsonSerializer.Serialize(o2,Options),Options);bool threw=false;try{new InventoryState(seed);}catch(ArgumentException){threw=true;}Check(threw,"ossuary is never admitted as a bag item");var bad=JsonSerializer.Deserialize<InventoryItem>(JsonSerializer.Serialize(o2,Options),Options);bad.affixes[0].tier=0;string r2;Check(!InventoryState.Admitted(bad,out r2),"ossuary with a rolled affix tier is refused");bad=JsonSerializer.Deserialize<InventoryItem>(JsonSerializer.Serialize(o2,Options),Options);bad.rarity=1;Check(!InventoryState.Admitted(bad,out r2),"ossuary with a non-unique rarity is refused");}
 {var inv=Fresh(o);inv.Bag[0].crystals=new[]{new InventoryCrystal{id="unsupported"}};Check(!inv.TryEquip(inv.Bag[0],1,out _),"relic-bearing item explicitly rejected");}
 }
 File.WriteAllText(args[0],JsonSerializer.Serialize(new{scope="standalone_source_inventory_oracle_not_Unity_runtime",passed=failed==0,failed,checks=Checks},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("INVENTORY_RESULT "+Checks.Count+" checks / "+failed+" failures");return failed==0?0:2;}
}
